"use strict";
import { useQuery } from "@tanstack/react-query";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { toGraphQLChain } from "uniswap/src/features/chains/utils";
import { ProtocolVersion } from "uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks";
import { getAbstractSubgraphs } from "uniswap/src/constants/abstractContracts";
import { fetchFromSubgraph } from "uniswap/src/utils/fetchSubgraph";
const V2_POOL_QUERY = `
  query GetV2Pool($poolAddress: String!) {
    pair(id: $poolAddress) {
      id
      token0 {
        id
        symbol
        name
        decimals
      }
      token1 {
        id
        symbol
        name
        decimals
      }
      reserve0
      reserve1
      reserveUSD
      totalSupply
      volumeUSD
      txCount
      stable
      createdAtTimestamp
      createdAtBlockNumber
    }
  }
`;
const V3_POOL_QUERY = `
  query GetV3Pool($poolAddress: String!) {
    pool(id: $poolAddress) {
      id
      token0 {
        id
        symbol
        name
        decimals
      }
      token1 {
        id
        symbol
        name
        decimals
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      token0Price
      token1Price
      totalValueLockedUSD
      totalValueLockedToken0
      totalValueLockedToken1
      volumeUSD
      txCount
      createdAtTimestamp
      createdAtBlockNumber
    }
  }
`;
async function fetchPoolFromSubgraph(subgraph, query, poolAddress) {
  try {
    const data = await fetchFromSubgraph(subgraph, {
      query,
      variables: { poolAddress: poolAddress.toLowerCase() },
      requestId: `useAbstractPoolData:${poolAddress}`
    });
    return data?.pair ?? data?.pool ?? null;
  } catch (error) {
    console.error("Failed to fetch pool from subgraph:", error);
    return null;
  }
}
function transformV2Pool(pool) {
  const reserve0 = parseFloat(pool.reserve0 || "0");
  const reserve1 = parseFloat(pool.reserve1 || "0");
  const tvlUSD = parseFloat(pool.reserveUSD || "0");
  let token0PriceUSD;
  let token1PriceUSD;
  if (reserve0 > 0 && reserve1 > 0 && tvlUSD > 0) {
    const r = reserve1 / reserve0;
    const p0 = tvlUSD / (reserve0 + reserve1 * r);
    if (isFinite(p0) && p0 > 0) {
      token0PriceUSD = p0;
      token1PriceUSD = r * p0;
    }
  }
  return {
    idOrAddress: pool.id,
    feeTier: 3e3,
    // V2 pools have 0.3% fee
    txCount: parseInt(pool.txCount || "0"),
    protocolVersion: ProtocolVersion.V2,
    token0: {
      id: pool.token0.id,
      address: pool.token0.id,
      symbol: pool.token0.symbol,
      name: pool.token0.name,
      decimals: parseInt(pool.token0.decimals)
    },
    tvlToken0: reserve0,
    token0Price: token0PriceUSD,
    token1: {
      id: pool.token1.id,
      address: pool.token1.id,
      symbol: pool.token1.symbol,
      name: pool.token1.name,
      decimals: parseInt(pool.token1.decimals)
    },
    tvlToken1: reserve1,
    token1Price: token1PriceUSD,
    volumeUSD24H: parseFloat(pool.volumeUSD || "0"),
    tvlUSD
  };
}
function transformV3Pool(pool) {
  const tickSpacing = parseInt(pool.tickSpacing);
  let feeTier = 3e3;
  const TICK_SPACING_TO_FEE = {
    1: 100,
    // 0.01%
    50: 500,
    // 0.05%
    100: 500,
    // 0.05%
    200: 3e3,
    // 0.3%
    2e3: 1e4
    // 1%
  };
  if (tickSpacing in TICK_SPACING_TO_FEE) {
    feeTier = TICK_SPACING_TO_FEE[tickSpacing];
  }
  const tvlToken0 = parseFloat(pool.totalValueLockedToken0 || "0");
  const tvlToken1 = parseFloat(pool.totalValueLockedToken1 || "0");
  const tvlUSD = parseFloat(pool.totalValueLockedUSD || "0");
  const tick = parseInt(pool.tick);
  const liquidity = parseFloat(pool.liquidity || "0");
  let token0PriceUSD;
  let token1PriceUSD;
  const r = pool.token1Price ? parseFloat(pool.token1Price) : void 0;
  if (tvlToken0 > 0 && tvlToken1 > 0 && tvlUSD > 0 && r && r > 0) {
    const p0 = tvlUSD / (tvlToken0 + tvlToken1 * r);
    if (isFinite(p0) && p0 > 0) {
      token0PriceUSD = p0;
      token1PriceUSD = r * p0;
    }
  }
  return {
    idOrAddress: pool.id,
    feeTier,
    txCount: parseInt(pool.txCount || "0"),
    protocolVersion: ProtocolVersion.V3,
    tickSpacing,
    tick,
    liquidity,
    token0: {
      id: pool.token0.id,
      address: pool.token0.id,
      symbol: pool.token0.symbol,
      name: pool.token0.name,
      decimals: parseInt(pool.token0.decimals)
    },
    tvlToken0,
    token0Price: token0PriceUSD,
    token1: {
      id: pool.token1.id,
      address: pool.token1.id,
      symbol: pool.token1.symbol,
      name: pool.token1.name,
      decimals: parseInt(pool.token1.decimals)
    },
    tvlToken1,
    token1Price: token1PriceUSD,
    volumeUSD24H: parseFloat(pool.volumeUSD || "0"),
    tvlUSD
  };
}
export function useAbstractPoolData(poolAddress, chainId = UniverseChainId.Mainnet) {
  const query = useQuery({
    queryKey: ["abstract-pool", poolAddress, chainId],
    queryFn: async () => {
      if (!poolAddress) {
        throw new Error("Pool address is required");
      }
      const subgraphs = getAbstractSubgraphs(chainId);
      const chain = toGraphQLChain(chainId);
      const v2Pool = await fetchPoolFromSubgraph(subgraphs.v2, V2_POOL_QUERY, poolAddress);
      if (v2Pool) {
        const data = transformV2Pool(v2Pool);
        data.token0 = { ...data.token0, chain };
        data.token1 = { ...data.token1, chain };
        return data;
      }
      const v3Pool = await fetchPoolFromSubgraph(subgraphs.v3, V3_POOL_QUERY, poolAddress);
      if (v3Pool) {
        const data = transformV3Pool(v3Pool);
        data.token0 = { ...data.token0, chain };
        data.token1 = { ...data.token1, chain };
        return data;
      }
      throw new Error("Pool not found in V2 or V3 subgraphs");
    },
    enabled: !!poolAddress,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    retry: 2
  });
  return {
    loading: query.isLoading,
    error: !!query.error,
    data: query.data
  };
}
