"use strict";
import { LiquidityPositionCard } from "components/Liquidity/LiquidityPositionCard";
import { getPositionUrl } from "components/Liquidity/utils";
import { Link } from "react-router-dom";
import { Flex } from "ui/src";
import { TransactionSettingsContextProvider } from "uniswap/src/features/transactions/settings/contexts/TransactionSettingsContext";
import { TransactionSettingKey } from "uniswap/src/features/transactions/settings/slice";
export function PoolDetailsPositionsTable({ positions }) {
  return <TransactionSettingsContextProvider settingKey={TransactionSettingKey.LP}>
      <Flex gap="$gap24" width="100%">
        {positions?.map((position) => <Link key={position.poolId} style={{ textDecoration: "none" }} to={getPositionUrl(position)}>
            <LiquidityPositionCard liquidityPosition={position} />
          </Link>)}
      </Flex>
    </TransactionSettingsContextProvider>;
}
